INSERT INTO `configurations` (`configuration_id`, `bundle_id`, `config_type`, `config_key`, `description`, `config_value`, `target`, `isPreLoginConfiguration`) VALUES ('170', 'NUO_CONFIG_BUNDLE', 'PREFERENCE', 'MORTGAGE_PURPOSE', 'mortgage purpose', '{\"ProductGroup\":[{\"productName\":\"First Time Buyer\",\"productRef\":\"FIRST.TIME.BUYER\",\"productDescription\":{\"notes\":\"You can make overpayments so you can reduce the size of your mortgage.|+|Choose your length of term – up to 30 years, so your monthly payments can suit you.\"},\"imageDetails\":[{\"imageUrl\":\"mortgage_lending.png\",\"imageType\":\"Icon\"}]}],\"ProductDetail\":[{\"ProductName\":\"First Time Buyer\",\"ProductDescription\":\"First Time Buyer\",\"ProductDetailedDescription\":\"Steping onto mortgage ladder,Find out how to buy a home and take out a mortgage.\",\"desc\":\" Deposit: We usually ask for 10% of the amount you want to borrow as a deposit.\",\"ProductNotes\":\"You can make overpayments so you can reduce the size of your mortgage.|+|Choose your length of term – up to 30 years, so your monthly payments can suit you.\",\"imageDetails\":[{\"imageUrl\":\"mortgages.png\",\"imageType\":\"Icon\"}],\"ProductTermsAndConditions\":\"1 Estimate obtained based on the information provided by the user. It does not constitute an offer for the application for a mortgage loan.<br>2 The application, granting and amount of the mortgage Loan will be subject to subsequent approval by our risks department.<br>3 Provided that you fulfil all our eligibilty requirements for a mortgage Loan.<br>4 Actual loan eligible amount depends on various factors such as credit history, prevailing interest rates and bank\'s credit policy.\"}]}', 'CLIENT', '1');

