INSERT INTO `emailtemplates` (`id`, `TemplateName`, `TemplateText`, `Subject`, `SenderName`, `SenderEmail`) VALUES ('130', 'RELATEDPARTY_STATUS_UPDATE', '<html> <head></head> <body> <table border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" align=\"center\" bgcolor=\"#FFFFFF\"> <tbody> <tr> <td style=\"width: 100%; vertical-align: middle; text-align: left; padding: 14px 24px; border-bottom: 3px solid #0A78D1; font-family: sans-serif; font-weight: 400;\"><img style=\"display: inline-blaock; float: left; vertical-align: middle;\" src=\"https://i.imgur.com/YWp6idv.png\" alt=\"logo\"></td></tr><tr> <td style=\"width: 100%; vertical-align: middle; text-align: left; padding: 25px 23px 0 23px; font-family: sans-serif; font-weight: 400;\"><span style=\"font-family: sans-serif; font-size: 12px; font-weight: 400; line-height: 14px; color: #000000; display: inline-block;\">Welcome</span><span style=\"font-family: sans-serif; font-size: 12px; font-weight: 400; line-height: 14px; color: #000000; display: inline-block;\">&nbsp;</span><span style=\"font-family: sans-serif; font-size: 12px; font-weight: bold; line-height: 14px; color: #000000; display: inline-block;\">%FirstName% %LastName%</span></td></tr><tr> <td style=\"width: 100%; vertical-align: middle; text-align: left; padding: 20px 23px 0 23px; font-family: sans-serif; font-weight: 300;\"><span style=\"font-family: sans-serif; font-size: 12px; font-weight: 400; line-height: 14px; color: #000000; display: inline-block;\">We would like to inform you that %CoApplicantFirstName% %CoApplicantLastName% has %Status% the application.</span></td></tr><tr> <td style=\"width: 100%; vertical-align: middle; text-align: left; padding: 23px 23px 0 23px; font-family: sans-serif; font-weight: 300;\"><span style=\"font-family: sans-serif; font-size: 12px; font-weight: 400; line-height: 14px; color: #000000; display: inline-block;\">Regards, </span></td></tr><tr> <td style=\"width: 100%; vertical-align: middle; text-align: left; padding: 4px 23px 27px 23px; font-family: sans-serif; font-weight: 300; border-bottom: 1px solid #0A78D1;\"><span style=\"font-family: sans-serif; font-size: 12px; font-weight: bold; line-height: 14px; color: #000000; display: inline-block;\">Temenos Digital Bank</span></td></tr><tr> <td style=\"width: 100%; vertical-align: middle; text-align: left; padding: 17px 23px 0px 23px; font-family: sans-serif; font-weight: 300;\"><span style=\"font-family: sans-serif; font-size: 11px; font-weight: 400; line-height: 13px; color: #000000; display: inline-block;\">This is a system generated mail. Please do not reply to this e-mail address.</span></td></tr><tr> <td style=\"width: 100%; vertical-align: middle; text-align: left; padding: 7px 23px 0px 23px; font-family: sans-serif; font-weight: 300;\"><span style=\"font-family: sans-serif; font-size: 12px; font-weight: bold; line-height: 14px; color: #000000; display: inline-block;\">Have any questions?</span></td></tr><tr> <td style=\"width: 100%; vertical-align: middle; text-align: left; padding: 7px 23px 0px 23px; font-family: sans-serif; font-weight: 300;\"> <div style=\"width: 100%; display: inline-block; padding: 18px 11px; vertical-align: middle; text-align: left; border-radius: 3px; border: 1px solid #E6E6E6; background-color: #ffffff;\"><span style=\"font-family: sans-serif; font-size: 12px; font-weight: 400; line-height: 14px; color: #000000; display: inline-block;\">Call us at</span> <span style=\"font-family: sans-serif; font-size: 12px; font-weight: bold; line-height: 14px; color: #000000; display: inline-block;\">&nbsp;1-800-412-5434&nbsp;</span> <span style=\"font-family: sans-serif; font-size: 12px; font-weight: 400; line-height: 14px; color: #000000; display: inline-block;\">for assistance.</span></div></td></tr><tr> <td style=\"width: 100%; vertical-align: middle; text-align: left; padding: 17px 23px 0px 23px; font-family: sans-serif; font-weight: 300;\"><span style=\"font-family: sans-serif; font-size: 10px; font-weight: 400; line-height: 12px; color: #000000; display: inline-block;\">CONFIDENTIALITY INFORMATION AND DISCLAIMER</span></td></tr><tr> <td style=\"width: 100%; vertical-align: middle; text-align: left; padding: 5px 23px 18px 23px; font-family: sans-serif; font-weight: 300;\"><span style=\"font-family: sans-serif; font-size: 10px; font-weight: 400; line-height: 12px; color: #000000; display: inline-block;\">This e-mail message and its attachments may contain confidential, proprietary or legally privileged information and is intended solely for the use of the individual or entity to whom it is addressed. If you have erroneously received this message, please delete it immediately and notify the sender. If you are not the intended recipient of the e-mail message you should not disseminate, distribute or copy this e-mail. E-mail transmission cannot be guaranteed to be secure or error-free as information could be intercepted, corrupted, lost, destroyed, incomplete or contain viruses and the Temenos Digital accepts no liability for any damage caused by the limitations of the e-mail transmission.</span></td></tr></tbody> </table> </body></html>', 'Related Party Response', 'Temenos Digital', 'dbx_cl@infinity.com');

UPDATE `configurations` SET `config_value` = '&emsp; 1.Proof of Identity\r\n&emsp;&emsp; a.Tax ID(mandatory)\r\n&emsp;&emsp; b.The ID which is entered under ID section to be pre populated\r\n(Any one document from below is Mandatory)\r\n&emsp;&emsp;&emsp;&emsp;  i. Driving License\r\n&emsp;&emsp;&emsp; &emsp; ii.Passport\r\n&emsp;&emsp;&emsp;&emsp;iii.Employee ID\r\n&emsp;&emsp;&emsp;&emsp; iv.Photo ID card issued by Local Government  <br>\r\n&emsp;2.Proof of Address : (Any one document from below is Mandatory)   \r\n&emsp;&emsp; a.Driving License    \r\n&emsp;&emsp; b.Passport    \r\n&emsp;&emsp; c.Utility Bills    \r\n&emsp;&emsp; d.Employer/HR letter   \r\n&emsp;&emsp; e.House Rent Contract <br>\r\n&emsp; 3.Proof of Income :    \r\n&emsp;&emsp;  a.For Status (Employment Status) - Salaried (Full Time Employee, Part Time Employee, Contract Employee, Casual Employee)    \r\n&emsp;&emsp;  &emsp;&emsp;     i.Pay-slips(mandatory) \r\n&emsp;&emsp;&emsp;    &emsp;  ii.Salary Account statement ( optional)    \r\n&emsp;&emsp; b.For Status(Employment Status) - Non-Salaried (Self-Employed, Retired,\r\n&emsp;&emsp;&emsp;Unemployed, Trainee)    \r\n&emsp;&emsp;&emsp;  &emsp;   i.Tax Return Statements(mandatory) \r\n&emsp;&emsp;&emsp;&emsp;   ii.Account Statements ( optional) <br>\r\n&emsp; 4.Product Document: First Time Buyer : (Add below documents if available)  \r\n&emsp;&emsp;  a.Initial/Advance Payment Receipt    \r\n&emsp;&emsp;  b.Sale Agreement    \r\n&emsp;&emsp;  c.Additional Mortgage Document <br>\r\n&emsp; 5.Property Document : (Add below documents if available)\r\n&emsp;&emsp;    a.Sale Deed    \r\n&emsp;&emsp;    b.Parent Document    \r\n&emsp;&emsp;    c.Plan Approval/Layout Approval \r\n&emsp;&emsp;    d.Property Tax Receipt    \r\n&emsp;&emsp;   e.Electricity, Water and Drainage Certificate/Receipt' WHERE (`configuration_id` = '254');
